#!/usr/bin/env bash
set -euo pipefail

# This script runs in a disposable Actions checkout, never a developer checkout.
if [[ "${GITHUB_ACTIONS:-}" != "true" ]]; then
  echo 'Run the Mipmap upstream sync workflow instead of running this locally.' >&2
  exit 1
fi

branch=mipmap/upstream-sync
existing=$(gh pr list --base main --head "$branch" --state open --json url --jq '.[0].url // empty')
if [[ -n "$existing" ]]; then
  echo "Pending update left intact: $existing" >> "$GITHUB_STEP_SUMMARY"
  exit 0
fi

git fetch --no-tags https://github.com/pingdotgg/t3code.git main
upstream=$(git rev-parse FETCH_HEAD)
if git merge-base --is-ancestor "$upstream" HEAD; then
  echo 'The fork already contains upstream main.' >> "$GITHUB_STEP_SUMMARY"
  exit 0
fi

git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git switch -C "$branch"
conflicts=false
if ! git merge --no-edit "$upstream"; then
  # A failed merge without unmerged files is an operational error, not a conflict.
  if [[ -z "$(git ls-files --unmerged)" ]]; then
    echo 'Upstream merge failed without merge conflicts.' >&2
    exit 1
  fi
  git diff --name-only --diff-filter=U > "$RUNNER_TEMP/upstream-conflicts.txt"
  git merge --abort
  # Propose upstream directly so GitHub exposes the conflicts against main.
  git switch -C "$branch" "$upstream"
  conflicts=true
fi

# Only this disposable automation branch can be replaced. Never force-push main.
git fetch origin "refs/heads/$branch:refs/remotes/origin/$branch" || {
  if git ls-remote --exit-code --heads origin "$branch"; then
    echo 'Could not fetch the existing automation branch.' >&2
    exit 1
  else
    status=$?
    [[ "$status" == 2 ]] || exit "$status"
  fi
}
expected=$(git rev-parse --verify "refs/remotes/origin/$branch" 2>/dev/null || true)
git push "--force-with-lease=refs/heads/$branch:$expected" origin "HEAD:refs/heads/$branch"

body="$RUNNER_TEMP/upstream-sync-body.md"
cat > "$body" <<EOF
Bring upstream T3 Code main ($upstream) into the Mipmap fork, preserving the fork's customizations.

This is a draft for review. No application checks have been run by the sync job.

GitHub suppresses push and pull_request workflows for changes created using GITHUB_TOKEN. A maintainer must close and reopen this PR to trigger PR checks, or run the appropriate checks explicitly. Upstream CI also requires its custom runners; configure usable fork runners before relying on those checks. Do not merge until applicable validation passes.

Follow .github/mipmap/maintenance.md when resolving conflicts. Keep the existing fork behavior and upstream fixes; never select an entire side automatically.

Generated by GitHub Actions using the Mipmap upstream sync workflow; no model or agent harness.
EOF
if [[ "$conflicts" == true ]]; then
  {
    echo
    echo 'The automatic merge found conflicts in:'
    echo '```text'
    cat "$RUNNER_TEMP/upstream-conflicts.txt"
    echo '```'
    echo 'This branch contains upstream main. Merge origin/main into this branch and resolve the conflicts before requesting review.'
  } >> "$body"
fi
if url=$(gh pr create --base main --head "$branch" --draft \
  --title 'chore(mipmap): merge upstream T3 Code updates' --body-file "$body" \
  2> "$RUNNER_TEMP/upstream-pr-error.txt"); then
  echo "Update prepared: $url" >> "$GITHUB_STEP_SUMMARY"
elif grep -qi 'not permitted to create or approve pull requests\|does not allow GitHub Actions to create or approve pull requests' "$RUNNER_TEMP/upstream-pr-error.txt"; then
  echo '::warning::Organization policy blocks PR creation with GITHUB_TOKEN. The update branch is ready; create the draft PR using the link in the job summary.'
  {
    echo "Update branch prepared. [Create the draft PR](https://github.com/$GH_REPO/compare/main...$branch?expand=1)."
    echo
    echo 'Automatic PR creation needs an organization policy change or the optional MIPMAP_UPSTREAM_SYNC_TOKEN repository secret.'
    echo
    cat "$body"
  } >> "$GITHUB_STEP_SUMMARY"
else
  cat "$RUNNER_TEMP/upstream-pr-error.txt" >&2
  exit 1
fi
